            elif current_step == 4:
                creation_state['character']['personality'] = message
            elif current_step == 5:
                creation_state['character']['ideals'] = message
            elif current_step == 6:
                creation_state['character']['bonds'] = message
            elif current_step == 7:
                creation_state['character']['flaws'] = message

            # Move to next step
            creation_state['step'] += 1

        # Determine next step
