class ActionType(Enum):
 SOCIAL = "social"
 TACTICAL = "tactical" 
 NARRATIVE = "narrative"
 CREATIVE = "creative"
 COMBAT = "combat"

class ChoiceOutcome(Enum):
 SUCCESS = "success"
 FAILURE = "failure"
 COMPLICATION = "complication"
 MIXED = "mixed"

@dataclass
class Character:
 name: str
 player_id: str
 backstory: Dict[str, Any] = field(default_factory=dict)
 traits: List[str] = field(default_factory=list)
 relationships: Dict[str, str] = field(default_factory=dict)
 goals: List[str] = field(default_factory=list)

class Choice:
 def init(self, description: str, action_type: ActionType, 
 difficulty: int = 10, consequences: Dict[str, Any] = None):
 self.description = description
 self.action_type = action_type
 self.difficulty = difficulty
 self.consequences = consequences or {}
 self.is_real = True # Prevents illusion of choice

@dataclass
class GameState:
